def mergePairs(a, b):
    i = j = 0
    out = []
    while i < len(a) and j < len(b):
        if a[i][0] < b[j][0]:
            out.append([a[i][0], a[i][1]])
            i += 1
        elif a[i][0] > b[j][0]:
            out.append([b[j][0], b[j][1]])
            j += 1
        else:
            out.append([a[i][0], a[i][1] + b[j][1]])
            i += 1
            j += 1
    while i < len(a):
        out.append([a[i][0], a[i][1]])
        i += 1
    while j < len(b):
        out.append([b[j][0], b[j][1]])
        j += 1
    return out
